import styles from './UserCommand.module.css'
import {useSessionContext} from '../../contexts/SessionContext'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {Stack} from '@primer/react'
import type {Command, CompletionUserMessage, UserCommandState} from '../../types/session'
import pluralize from 'pluralize'
import {isActiveSession} from '../../types/session'

type UserCommandDisplayState = 'queued' | 'in_logs' | 'failed' | 'dismissed'
type DisplayCommand = {
  state: UserCommandDisplayState
  content: string
}

function stateToDescriptors({state, count}: {state: UserCommandDisplayState; count: number}) {
  const descriptors: Record<
    UserCommandDisplayState,
    {actionText?: string; postScript?: string; containerStateClass?: string}
  > = {
    queued: {actionText: 'Queued for Copilot', containerStateClass: styles.containerMuted},
    failed: {
      actionText: `Unable to submit ${pluralize('message', count)}`,
      containerStateClass: styles.containerMuted,
    },
    in_logs: {},
    dismissed: {
      actionText: `Copilot finished the session before it could pick up ${pluralize('this', count)} ${pluralize(
        'message',
        count,
      )}`,
      containerStateClass: styles.containerMuted,
    },
  }

  return descriptors[state]
}

// inLogs indicates whether we're displaying this command embedded in the logs or above the chat window
function getDisplayState({
  sessionIsActive,
  commandState,
  inLogs,
}: {
  sessionIsActive: boolean
  commandState: UserCommandState
  inLogs: boolean
}): UserCommandDisplayState {
  if (inLogs) {
    return 'in_logs'
  }
  const happyPathStates = ['queued', 'in_progress', 'completed']
  const unhappyPathStates = ['failed', 'dismissed']

  if (!sessionIsActive && happyPathStates.includes(commandState)) {
    // if a session is finished and the command isn't in the logs, something went wrong
    return 'dismissed'
  } else if (happyPathStates.includes(commandState)) {
    return 'queued'
  } else if (unhappyPathStates.includes(commandState)) {
    return commandState as UserCommandDisplayState
  } else {
    throw new Error(`Unexpected command state: ${commandState}`)
  }
}

export function LogCommands({
  rawCommands,
  commandData,
}: {
  rawCommands: CompletionUserMessage[]
  commandData: Command[]
}) {
  const commands: DisplayCommand[] = []
  const {session} = useSessionContext()
  const sessionIsActive = isActiveSession(session)
  for (const rawCommand of rawCommands) {
    const command = findCommandByID(commandData, rawCommand)
    let processedCommand: DisplayCommand
    if (command) {
      const state = getDisplayState({sessionIsActive, commandState: command.state, inLogs: true})
      processedCommand = {state, content: command.content}
      commands.push(processedCommand)
    }
  }
  return <ProcessedUserCommands commands={commands} />
}

// Commands that are not yet in the logs
export function ChatCommands({commands}: {commands: Command[]}) {
  const processedCommands: DisplayCommand[] = []
  const {session} = useSessionContext()
  const sessionIsActive = isActiveSession(session)
  for (const command of commands) {
    const state = getDisplayState({sessionIsActive, commandState: command.state, inLogs: false})
    const processedCommand = {state, content: command.content}
    processedCommands.push(processedCommand)
  }
  return <ProcessedUserCommands commands={processedCommands} />
}

export function ProcessedUserCommands({commands}: {commands: DisplayCommand[]}) {
  const commandsByState: Array<{state: UserCommandDisplayState; commands: string[]}> = []
  for (const command of commands) {
    const lastGroup = commandsByState[commandsByState.length - 1]
    if (lastGroup?.state === command.state) {
      lastGroup.commands.push(command.content)
    } else {
      commandsByState.push({state: command.state, commands: [command.content]})
    }
  }
  return (
    <>
      {commandsByState.map((commandGroup, index) => (
        <UserCommandGroup key={index} contents={commandGroup.commands} state={commandGroup.state} />
      ))}
    </>
  )
}

function UserCommandGroup({contents, state}: {contents: string[]; state: UserCommandDisplayState}) {
  const descriptors = stateToDescriptors({state, count: contents.length})
  const actionText = descriptors.actionText
  const containerStateClass = descriptors.containerStateClass
  return (
    <Stack>
      <div className={`mb-2 ${styles.commandContainer} ${containerStateClass ?? ''}`}>
        {actionText && <div className={`mb-2 ${styles.actionText}`}>{actionText}</div>}
        {contents.map((content, index) => (
          <UserCommand key={index} content={content} />
        ))}
      </div>
    </Stack>
  )
}

function UserCommand({content}: {content: string}) {
  const {sessionOwner} = useSessionContext()
  const displayName = sessionOwner?.login ?? 'user'

  return (
    <div className="mb-2">
      <Stack align="center" direction="horizontal" gap="condensed">
        <span className={`p-2 ${styles.commandBox}`}>{content}</span>
        {sessionOwner?.primaryAvatarUrl && (
          <GitHubAvatar
            src={sessionOwner.primaryAvatarUrl}
            alt={`${displayName}'s avatar`}
            size={28}
            className="ml-1"
          />
        )}
      </Stack>
    </div>
  )
}

function findCommandByID(commandData: Command[], logEntry: CompletionUserMessage) {
  const matchingCommand = commandData.find(command => `command-${command.external_id}` === logEntry.source)
  if (!matchingCommand) {
    return null // Skip if no matching command is found
  }
  if (typeof logEntry.content !== 'string') {
    return null // Skip non-string content for now
  }

  return matchingCommand
}

try{ LogCommands.displayName ||= 'LogCommands' } catch {}
try{ ChatCommands.displayName ||= 'ChatCommands' } catch {}
try{ ProcessedUserCommands.displayName ||= 'ProcessedUserCommands' } catch {}
try{ UserCommandGroup.displayName ||= 'UserCommandGroup' } catch {}
try{ UserCommand.displayName ||= 'UserCommand' } catch {}