import {CopilotAnimationType} from '@github-ui/copilot-animation'
import {AgentAvatar} from '../AgentAvatar'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {WithShimmerEffect} from '@github-ui/copilot-chat/components/WithShimmerEffect'
import {Stack} from '@primer/react'
import {useState, useRef, useEffect} from 'react'

const predefinedMessages = [
  'Spinning up dev environment…',
  'Fueling the runtime engines…',
  'Clearing the airspace for MCP traffic…',
  'Cabin pressure stable. Almost ready…',
  'Reticulating goggles...',
  'Calibrating flux capacitor...',
  'Adjusting seatbelt…',
  'Waiting for clearance from GitHub tower…',
  'Final systems check, standing by…',
  'Takeoff soon™…',
]

export function BootingUpMessage({agentId}: {agentId?: number}) {
  const [loadingMessageIndex, setLoadingMessageIndex] = useState(0)
  const intervalRef = useRef<NodeJS.Timeout | null>(null)

  useEffect(() => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current)
      intervalRef.current = null
    } else {
      intervalRef.current = setInterval(() => {
        setLoadingMessageIndex(prev => {
          if (prev < predefinedMessages.length - 1) {
            return prev + 1
          }
          return prev // stay on last message
        })
      }, 7000)
    }

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current)
        intervalRef.current = null
      }
    }
  }, [])
  // We should never hit the fallback case, but typescript complains if we don't handle it
  return <LoadingMessage message={predefinedMessages[loadingMessageIndex] || 'Loading…'} agentId={agentId} />
}

export function LoadingMessage({message, agentId}: {message: string; agentId?: number}) {
  return (
    <Stack direction="horizontal" padding="none" align="center" justify="start" gap="condensed">
      <AgentAvatar animationType={CopilotAnimationType.Thinking} loopAnimation agentId={agentId} />
      <WithShimmerEffect className="color-fg-muted">{message}</WithShimmerEffect>
    </Stack>
  )
}

try{ BootingUpMessage.displayName ||= 'BootingUpMessage' } catch {}
try{ LoadingMessage.displayName ||= 'LoadingMessage' } catch {}