import type {Session} from '../types/session'
import {useQuery} from '@github-ui/react-query'
import type {PublicUser} from '../types/public-user'

export function useSessionOwners({
  sessions,
  initialData,
}: {
  sessions: Session[] | undefined
  initialData?: PublicUser[]
}) {
  const userIds = getSortedUserIds(sessions || [])
  return useQuery<PublicUser[]>({
    queryKey: ['agent-sessions-users', userIds],
    queryFn: async () => {
      const response = await fetch(`/copilot/agent-sessions/users?user_ids=${encodeURIComponent(userIds)}`, {
        headers: {
          Accept: 'application/json',
          'X-Requested-With': 'XMLHttpRequest',
        },
      })
      if (!response.ok) {
        throw new Error('Failed to fetch session owners')
      }
      const data = await response.json()
      const users = data.users as PublicUser[]
      return users
    },
    initialData,
  })
}

function getSortedUserIds(sessions: Session[]): string {
  const userIdSet = new Set<number>()
  for (const session of sessions) {
    userIdSet.add(session.user_id)
  }
  return Array.from(userIdSet)
    .sort((a, b) => a - b)
    .join(',')
}
