import {useCAPIQuery} from './useCAPIQuery'
import {isPendingSession, type CommandsResponse} from '../types/session'
import {useSessionContext} from '../contexts/SessionContext'
import {fetchCAPI} from '../utils/fetch-capi'
import {useQueryClient} from '@github-ui/react-query'

export interface UseListCommandsProps {
  pollingInterval: number
}

export function useListCommands({pollingInterval}: UseListCommandsProps) {
  const {session} = useSessionContext()
  const activeSessionId = session.id
  const queryClient = useQueryClient()
  const queryKey = ['agent-session-commands', activeSessionId]

  const query = useCAPIQuery<CommandsResponse>({
    queryKey,
    queryFn: async ({queryKey: currentQueryKey}) => {
      const result = await fetchCAPI({
        path: `/agents/sessions/${activeSessionId}/commands?sort=created_at,asc`,
        method: 'GET',
      })

      if (!result.ok) {
        throw new Error(`Failed to fetch commands: ${result.statusText}`)
      }

      const serverData = (await result.json()) as CommandsResponse

      // Get current cache data to preserve optimistic commands
      const currentData = queryClient.getQueryData<CommandsResponse>(currentQueryKey)

      if (currentData) {
        const optimisticCommands = currentData.commands.filter(cmd => cmd.id.startsWith('optimistic-'))

        // Merge server commands with optimistic commands (optimistic commands go at the end since they're the newest)
        return {
          commands: [...serverData.commands, ...optimisticCommands],
        }
      }

      return serverData
    },
    refetchInterval: () => {
      if (session.state === 'in_progress' || session.state === 'queued') {
        return pollingInterval
      }
      return false
    },
    enabled: !isPendingSession(session),
  })

  return {
    data: query.data?.commands ?? [],
    isLoading: query.isLoading,
    isError: query.isError,
    error: query.error,
  }
}
