import {
  CodespacesIcon,
  DotFillIcon,
  FileAddedIcon,
  FileDiffIcon,
  FileIcon,
  LightBulbIcon,
  TerminalIcon,
} from '@primer/octicons-react'
import type {ToolName} from '../../../types/session'

export function getToolIcon(toolName: ToolName = '') {
  switch (toolName) {
    case 'bash':
      return <TerminalIcon aria-label="CLI output: " />
    case 'think':
      return <LightBulbIcon aria-label="Copilot Thought: " />
    case 'str_replace_editor':
    case 'str_replace':
    case 'edit':
      return <FileDiffIcon className="fgColor-attention" aria-label="File Edit: " />
    case 'create':
      return <FileAddedIcon className="fgColor-success" aria-label="File Creation: " />
    case 'view':
      return <FileIcon aria-label="File View: " />
    case 'run_custom_setup_step':
      return <CodespacesIcon aria-label="Custom Setup Run: " />
    case 'report_progress':
    case 'reply_to_comment':
    default:
      return <DotFillIcon size={12} aria-label="Tool output: " />
  }
}
