import {createContext, useContext, useMemo} from 'react'

type SessionLogsVariant = 'default' | 'mission-control' | 'chat'

/**
 * context to optionally allow consumers of SessionLogs to modify its behavior based on the variant
 * without Provider it returns default
 */
type Context = {
  variant: SessionLogsVariant
  onToolExpand: null | ((expand: boolean) => void)
}

export const SessionLogsContext = createContext<Context>({
  variant: 'default',
  onToolExpand: null,
})

export function useSessionLogsContext() {
  return useContext(SessionLogsContext)
}

type SessionLogsProviderProps = {
  variant: SessionLogsVariant
  children: React.ReactNode
  onToolExpand?: Context['onToolExpand']
}

export function SessionLogsProvider({variant, onToolExpand = null, children}: SessionLogsProviderProps) {
  return (
    <SessionLogsContext.Provider value={useMemo(() => ({variant, onToolExpand}), [variant, onToolExpand])}>
      {children}
    </SessionLogsContext.Provider>
  )
}

try{ SessionLogsContext.displayName ||= 'SessionLogsContext' } catch {}
try{ SessionLogsProvider.displayName ||= 'SessionLogsProvider' } catch {}