export function ToolRenderer({
  name,
  delta,
  args,
  mcpToolNameMappings,
}: {
  name: ToolName
  delta: Delta
  args: ToolArgs
  mcpToolNameMappings?: Record<string, string>
}) {
  const isSessionCommandsEnabled = useFeatureFlag('copilot_swe_agent_progress_commands')
  switch (name) {
    case 'bash': {
      const bashArgs = args as BashToolArgs
      const input = `$ ${bashArgs.command}`
      const title = bashArgs.description ? `Bash: ${bashArgs.description}` : `Run Bash command`
      const {isError, content: output} = parseContent(delta.content)
      const isPending = output === undefined

      return (
        <Tool
          title={title}
          isError={isError}
          isPending={isPending}
          toolHeaderProps={{leadingVisual: getToolIcon(name)}}
        >
          <ToolPrimaryContent
            language={bashArgs.command?.startsWith('git diff') ? 'diff' : 'bash'}
            markdown={`${input}${output ? `\n${output}` : ''}`}
            bashLoading={isPending}
          />
        </Tool>
      )
    }

    case 'github-mcp-server-web_search':
    case 'github-mcp-server-bing_search': {
      const webSearchArgs = args as GitHubMCPServerWebSearchToolArgs
      const title = `Web Search: ${webSearchArgs.query}`
      const {isError, content: output} = parseContent(delta.content)

      return (
        <Tool title={title} isError={isError} toolHeaderProps={{leadingVisual: getToolIcon(name)}}>
          <ToolPrimaryContent language="json" markdown={output} />
        </Tool>
      )
    }

    case 'write_bash': {
      const writeBashArgs = args as WriteBashToolArgs
      const input = `$ ${writeBashArgs.input}`
      const {isError, content: output} = parseContent(delta.content)
      const isPending = output === undefined

      return (
        <Tool
          title={`Send input to Bash session ${writeBashArgs.sessionId}`}
          isError={isError}
          isPending={isPending}
          toolHeaderProps={{leadingVisual: getToolIcon(name)}}
        >
          <ToolPrimaryContent
            language="bash"
            markdown={`${input}${output ? `\n${output}` : ''}`}
            bashLoading={isPending}
          />
        </Tool>
      )
    }

    case 'read_bash': {
      const readBashArgs = args as ReadBashToolArgs
      const {isError, content: output} = parseContent(delta.content)
      const isPending = output === undefined

      return (
        <Tool
          title={`Read logs from Bash session ${readBashArgs.sessionId}`}
          isError={isError}
          isPending={isPending}
          toolHeaderProps={{leadingVisual: getToolIcon(name)}}
        >
          <ToolPrimaryContent language="bash" markdown={output ? `\n${output}` : ''} bashLoading={isPending} />
        </Tool>
      )
    }

    case 'stop_bash': {
      const stopBashArgs = args as StopBashToolArgs
      const {isError, content: output} = parseContent(delta.content)
      const isPending = output === undefined

      return (
        <Tool
          title={`Stop Bash session ${stopBashArgs.sessionId}`}
          isError={isError}
          isPending={isPending}
          toolHeaderProps={{leadingVisual: getToolIcon(name)}}
        >
          <ToolPrimaryContent language="bash" markdown={output ? output : ''} bashLoading={isPending} />
        </Tool>
      )
    }

    case 'think': {
      const thinkArgs = args as ThinkToolArgs
      const {isError, content: output} = parseContent(thinkArgs.thought)

      return (
        <Tool title={'Thought'} isError={isError} toolHeaderProps={{leadingVisual: getToolIcon(name)}}>
          <ToolPrimaryContent language="markdown" markdown={output} />
        </Tool>
      )
    }

    case 'run_custom_setup_step': {
      const runCustomSetupStepArgs = args as RunCustomSetupStepToolArgs
      const {isError, content: output} = parseContent(delta.content)
      const title = !runCustomSetupStepArgs.name?.trim()
        ? 'Run custom setup step'
        : `Run "${runCustomSetupStepArgs.name.trim()}" custom setup step`
      const isPending = output === undefined

      return (
        <Tool
          title={title}
          isError={isError}
          isPending={isPending}
          toolHeaderProps={{leadingVisual: getToolIcon(name)}}
        >
          <ToolPrimaryContent language="console" markdown={output} bashLoading={isPending} />
        </Tool>
      )
    }

    case 'run_setup': {
      const runSetupArgs = args as RunSetupArgs
      const {isError, content: output} = parseContent(delta.content)
      const title = runSetupArgs.name.trim()
      const isPending = output === undefined

      return (
        <Tool
          title={title}
          isError={isError}
          isPending={isPending}
          toolHeaderProps={{leadingVisual: getToolIcon(name)}}
        >
          <ToolPrimaryContent language="console" markdown={output} bashLoading={isPending} />
        </Tool>
      )
    }

    case 'str_replace_editor':
    case 'create':
    case 'str_replace':
    case 'edit':
    case 'view': {
      const strReplaceEditorArgs = args as StrReplaceEditorToolArgs

      // If there's no `.command` then the agent is using discrete editing tools, and we'll fallback to `name` as the command
      const command = name === 'edit' ? 'str_replace' : strReplaceEditorArgs.command || name

      const fileExtension = strReplaceEditorArgs.path?.split('.').pop() || ''
      // TODO: We need a more robust way to determine the language from the file extension using a pre-existing library mapper
      const language = fileExtension === 'md' ? 'markdown' : fileExtension || 'text'
      const {isError, content: parsedContent} = parseContent(delta.content)
      switch (command) {
        case 'create':
        case 'insert':
        case 'view':
        case 'undo_edit': {
          // TODO: differentiate files/directory for str_replace_editor/view
          const output = extractContentFromDiff(parsedContent)

          const filePath = trimFileName(strReplaceEditorArgs.path)
          const displayPath =
            filePath + getPathSuffix(command, strReplaceEditorArgs.view_range, strReplaceEditorArgs.insert_line)

          return (
            <Tool
              title={getCommandTitle({
                command,
                path: strReplaceEditorArgs.path,
              })}
              isError={isError}
              path={filePath ? displayPath : undefined}
              toolHeaderProps={{leadingVisual: getToolIcon(name)}}
            >
              <ToolPrimaryContent language={language} markdown={output} />
            </Tool>
          )
        }

        case 'str_replace': {
          const output = parsedContent?.trim()

          if (output && isSessionCommandsEnabled) {
            const diffLines = parseUnifiedDiff(output)

            if (diffLines.length > 0) {
              return (
                <Tool
                  title={getCommandTitle({
                    command,
                    path: strReplaceEditorArgs.path,
                  })}
                  isError={isError}
                  path={trimFileName(strReplaceEditorArgs.path)}
                  toolHeaderProps={{leadingVisual: getToolIcon(name)}}
                >
                  <StaticUnifiedDiffPreview diffLines={diffLines} tabSize={4} className={styles.diffPreview} />
                </Tool>
              )
            }
          }

          return (
            <Tool
              title={getCommandTitle({
                command,
                path: strReplaceEditorArgs.path,
              })}
              isError={isError}
              path={trimFileName(strReplaceEditorArgs.path)}
              toolHeaderProps={{leadingVisual: getToolIcon(name)}}
            >
              <ToolPrimaryContent language={'diff'} markdown={output} />
            </Tool>
          )
        }
      }
      // This actually isn't needed, but the linter complains if we don't have it.
      break
    }

    case 'report_progress': {
      const reportProgressArgs = args as ReportProgressToolArgs
      const {isError: outputError, content: output} = parseContent(delta.content)

      if ('prDescription' in reportProgressArgs) {
        const {isError: inputError, content: input} = parseContent(reportProgressArgs.prDescription)

        // Extract only the first line of the commit message for the title
        const firstLineOfCommitMessage =
          reportProgressArgs.commitMessage.split('\n')[0] || reportProgressArgs.commitMessage

        return (
          <Tool
            title={`Progress update: ${firstLineOfCommitMessage}`}
            isError={inputError || outputError}
            toolHeaderProps={{leadingVisual: getToolIcon(name)}}
          >
            <ToolPrimaryContent language="markdown" markdown={input} />
            <ToolSecondaryContent type="output" language="json" markdown={output} />
          </Tool>
        )
      } else {
        return (
          <Tool
            title={`Start next task: ${reportProgressArgs.nextTask}`}
            isError={outputError}
            toolHeaderProps={{leadingVisual: getToolIcon(name)}}
          >
            <ToolPrimaryContent language="markdown" markdown={reportProgressArgs.tasksChecklist} />
          </Tool>
        )
      }
    }

    case 'commit_changes': {
      const commitChangesArgs = args as CommitChangesToolArgs
      const {isError: outputError, content: output} = parseContent(delta.content)

      // Extract only the first line of the commit message for the title
      const firstLineOfCommitMessage = commitChangesArgs.commitMessage.split('\n')[0] || commitChangesArgs.commitMessage

      return (
        <Tool
          title={`Commit changes: ${firstLineOfCommitMessage}`}
          isError={outputError}
          toolHeaderProps={{leadingVisual: getToolIcon(name)}}
        >
          <ToolSecondaryContent type="output" language="json" markdown={output} />
        </Tool>
      )
    }

    // TODO: We have the comment_id in the args, so we can link to the comment in the UI once we have a design
    case 'reply_to_comment': {
      const replyToCommentArgs = args as ReplyToCommentToolArgs
      const {isError, content: output} = parseContent(replyToCommentArgs.reply)
      return (
        <Tool title={'Reply to comment'} isError={isError} toolHeaderProps={{leadingVisual: getToolIcon(name)}}>
          <ToolPrimaryContent language={'markdown'} markdown={output} />
        </Tool>
      )
    }

    // The remaining tools have been removed, but we need to continue to support them for old sessions
    case 'async_bash': {
      const asyncBashArgs = args as AsyncBashToolArgs
      const input = `$ ${asyncBashArgs.command}`
      const {isError, content: output} = parseContent(delta.content)
      const isPending = output === undefined

      return (
        <Tool
          title={`Start or send input to long-running Bash session ${asyncBashArgs.sessionId}`}
          isError={isError}
          isPending={isPending}
          toolHeaderProps={{leadingVisual: getToolIcon(name)}}
        >
          <ToolPrimaryContent
            language="bash"
            markdown={`${input}${output ? `\n${output}` : ''}`}
            bashLoading={isPending}
          />
        </Tool>
      )
    }
    case 'read_async_bash': {
      const readAsyncBashArgs = args as ReadAsyncBashToolArgs
      const {isError, content: output} = parseContent(delta.content)
      const isPending = output === undefined

      return (
        <Tool
          title={`View logs from long-running Bash session ${readAsyncBashArgs.sessionId}`}
          isError={isError}
          isPending={isPending}
          toolHeaderProps={{leadingVisual: getToolIcon(name)}}
        >
          <ToolPrimaryContent language="bash" markdown={output ? output : ''} bashLoading={isPending} />
        </Tool>
      )
    }
    case 'stop_async_bash': {
      const stopAsyncBashArgs = args as StopAsyncBashToolArgs
      const {isError, content: output} = parseContent(delta.content)
      const isPending = output === undefined

      return (
        <Tool
          title={`Stop long-running Bash session ${stopAsyncBashArgs.sessionId}`}
          isError={isError}
          isPending={isPending}
          toolHeaderProps={{leadingVisual: getToolIcon(name)}}
        >
          <ToolPrimaryContent language="bash" markdown={output ? output : ''} bashLoading={isPending} />
        </Tool>
      )
    }

    case 'code_review': {
      const {isError, content} = parseContent(delta.content)
      const title = CODE_REVIEW_TITLE
      let displayText: string
      if (isCodeReviewToolArgs(args)) {
        const {prTitle, prDescription} = args
        displayText = `#### ${prTitle}\n\n${prDescription}`
      } else {
        displayText = 'No code review details provided.'
      }
      displayText += `\n\n---\n\n${content}`
      return (
        <Tool title={title} isError={isError}>
          <ToolPrimaryContent language="markdown" markdown={displayText} />
        </Tool>
      )
    }

    default: {
      const {isError, content} = parseContent(delta.content)
      const {language: outputLanguage, output} = parseGenericToolOutput(content)
      const input = Object.keys(args).length === 0 ? null : JSON.stringify(args, null, 2)
      const title = TOOL_CALL_TITLES[name] || `Call to ${mcpToolNameMappings?.[name] || name}`

      return (
        <Tool title={title} isError={isError} toolHeaderProps={{leadingVisual: getToolIcon(name)}}>
          {input && <ToolSecondaryContent type="input" language="json" markdown={input} />}
          <ToolPrimaryContent language={outputLanguage} markdown={output} />
        </Tool>
      )
    }
  }
}

const parseGenericToolOutput = (content: string | undefined): {language: string; output: string | undefined} => {
  if (typeof content === 'undefined') {
    return {language: 'text', output: content}
  }

  try {
    const parsedOutput = JSON.parse(content)
    const output = JSON.stringify(parsedOutput, null, 2)
    return {language: 'json', output}
  } catch {
    return {language: 'text', output: content}
  }
}

function shouldWrapInCodeBlock(language: string): boolean {
  return !(language === 'markdown' || language === 'text' || language === '')
}

export function Tool({
  title,
  isError = false,
  isPending = false,
  path,
  toolHeaderProps,
  children,
  isOpenOverride,
}: {
  title: string
  isError: boolean
  isPending?: boolean
  path?: string
  toolHeaderProps?: ToolHeaderPropsType
  children: ReactNode
  isOpenOverride?: boolean
}) {
  const {variant} = useSessionLogsContext()

  // Use isOpenOverride as the initial value, but allow user to toggle manually
  const [isDetailsOpen, setIsDetailsOpen] = useState(isOpenOverride ?? false)
  const hasUserToggledRef = useRef(false)
  const prevIsOpenOverrideRef = useRef(isOpenOverride)

  // Sync with isOpenOverride changes, but only if user hasn't manually toggled
  // Reset user toggle flag when isOpenOverride changes
  useEffect(() => {
    if (prevIsOpenOverrideRef.current !== isOpenOverride) {
      prevIsOpenOverrideRef.current = isOpenOverride
      hasUserToggledRef.current = false
      if (isOpenOverride !== undefined) {
        setIsDetailsOpen(isOpenOverride)
      }
    }
  }, [isOpenOverride])

  const toolInstanceRef = useRef({})
  const detailsRef = useRef<HTMLDetailsElement>(null)

  const handlerRef = useRef<((event: Event) => void) | null>(null)

  // eslint-disable-next-line react-hooks/refs
  handlerRef.current = (event: Event) => {
    const customEvent = event as CustomEvent<{expand: boolean; excludeInstance: object}>
    if (customEvent.detail.excludeInstance !== toolInstanceRef.current && detailsRef.current) {
      // Update both React state and native element state together
      const shouldExpand = customEvent.detail.expand
      detailsRef.current.open = shouldExpand
      setIsDetailsOpen(shouldExpand)
    }
  }

  // Listen for global expand/collapse events
  useEffect(() => {
    const handler = (event: Event) => {
      handlerRef.current?.(event)
    }

    document.addEventListener('tool-global-toggle', handler)
    return () => {
      document.removeEventListener('tool-global-toggle', handler)
    }
  }, [])

  // Sync React state with native details element's open state
  useEffect(() => {
    const detailsElement = detailsRef.current
    if (!detailsElement) return

    // Only set initial state if we're not using isOpenOverride
    if (isOpenOverride === undefined) {
      setIsDetailsOpen(detailsElement.hasAttribute('open'))
    }

    const observer = new MutationObserver(() => {
      setIsDetailsOpen(detailsElement.hasAttribute('open'))
    })

    observer.observe(detailsElement, {
      attributes: true,
      attributeFilter: ['open'],
    })

    return () => observer.disconnect()
  }, [isOpenOverride])

  const handleModifierClick = (expand: boolean) => {
    // Mark that user has manually toggled
    hasUserToggledRef.current = true

    // Update both React state and native element state together
    if (detailsRef.current) {
      detailsRef.current.open = expand
    }
    setIsDetailsOpen(expand)

    // Dispatch event to all other tools
    const event = new CustomEvent('tool-global-toggle', {
      detail: {expand, excludeInstance: toolInstanceRef.current},
    })
    document.dispatchEvent(event)
  }

  const handleToggle = (event: React.SyntheticEvent<HTMLDetailsElement>) => {
    // Mark that user has manually toggled
    hasUserToggledRef.current = true
    setIsDetailsOpen(event.currentTarget.open)
  }

  const isToolHeaderIconEnabled = isFeatureEnabled('mission_control_use_tool_header_icons')

  return (
    <details
      ref={detailsRef}
      open={isDetailsOpen}
      onToggle={handleToggle}
      className={clsx(styles.detailsContainer, {
        [styles.detailsContainerDefault]: variant === 'default',
      })}
    >
      <ToolHeader
        leadingVisual={isToolHeaderIconEnabled ? toolHeaderProps?.leadingVisual : undefined}
        title={title}
        path={path}
        isCollapsed={!isDetailsOpen}
        isPending={isPending}
        isError={isError}
        onModifierClick={handleModifierClick}
      />
      <div className={variant === 'default' ? `border-top ${styles.toolContent}` : styles.toolContentMissionControl}>
        {children}
      </div>
    </details>
  )
}

export function ToolPrimaryContent({
  language,
  markdown,
  ...extensionProps
}: {
  language: string
  markdown: string | undefined
} & ToolCodeBlockExtensionArgs) {
  const {markdown: truncatedMarkdown} = truncateMarkdownContent(markdown)

  return markdown === undefined ? (
    <MarkdownLoading />
  ) : (
    <MarkdownRenderer
      markdown={
        shouldWrapInCodeBlock(language)
          ? wrapInCodeBlock({language, markdown: truncatedMarkdown || ''})
          : truncatedMarkdown || ''
      }
      extensions={[toolCodeBlockExtension({...extensionProps})]}
      // Code gets rendered with padding so we need to apply padding to content not being wrapped in a code block
      className={clsx(!shouldWrapInCodeBlock(language) && 'p-3')}
    />
  )
}

function ToolSecondaryContent({
  type,
  language,
  markdown,
}: {
  type: 'input' | 'output'
  language: string
  markdown: string | undefined
}) {
  const {markdown: truncatedMarkdown} = truncateMarkdownContent(markdown)

  return (
    <Stack direction="vertical" padding="normal" gap="condensed">
      <Text size="small" weight="medium" className={'fgColor-muted'}>
        {type === 'input' ? 'Input' : 'Output'}
      </Text>
      {markdown === undefined ? (
        <MarkdownLoading />
      ) : (
        <MarkdownRenderer
          // Code gets rendered with padding so we need to apply padding to content not being wrapped in a code block
          className={clsx(!shouldWrapInCodeBlock && 'p-3', 'border rounded bgColor-default overflow-hidden')}
          markdown={wrapInCodeBlock({
            language,
            markdown: truncatedMarkdown || '',
          })}
          extensions={[toolCodeBlockExtension()]}
        />
      )}
    </Stack>
  )
}

function MarkdownLoading({lines = 3, maxWidth = '45ch'}: {lines?: number; maxWidth?: string}) {
  return (
    // Padding matches the default padding of the MarkdownRenderer
    <div className="py-3 px-4">
      {/* eslint-disable-next-line primer-react/no-system-props */}
      <SkeletonText lines={lines} maxWidth={maxWidth} />
    </div>
  )
}

// Parses the delta.content for <error> tags to detect errors and remove tags from content
function parseContent(content?: string): {isError: boolean; content: string | undefined} {
  if (!content) return {isError: false, content}

  const errorRegex = /<error>(.*?)<\/error>/s
  const match = content.match(errorRegex)

  if (match && match[1] !== undefined) {
    return {
      isError: true,
      content: match[1], // This gets the content between the error tags
    }
  }

  return {isError: false, content}
}

const getCommandTitle = ({command, path}: {command: StrReplaceEditorToolArgs['command']; path: string}) => {
  const hasPath = !!trimFileName(path)?.length

  switch (command) {
    case 'create':
      return 'Create'
    case 'insert':
      return 'Insert lines at'
    case 'view':
      return `View${hasPath ? '' : ' repository'}`
    case 'str_replace':
      return 'Edit'
    case 'undo_edit':
      return 'Undo edit'
    default:
      return command || 'Unknown'
  }
}

const getPathSuffix = (command: StrReplaceEditorToolArgs['command'], viewRange?: number[], insertLine?: number) => {
  if (command === 'view' && viewRange) {
    return `:${viewRange[0]}-${viewRange[1]}`
  }

  if (command === 'insert' && insertLine !== undefined) {
    return `:${insertLine}`
  }

  return ''
}

function isCodeReviewToolArgs(args: ToolArgs): args is CodeReviewToolArgs {
  return 'prTitle' in args && 'prDescription' in args
}

