import {useCAPIQuery} from './useCAPIQuery'
import {SessionState, type LogEntry, type StreamingMessage, isValidLogEntry, isPendingSession} from '../types/session'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {CopilotChatMessageStreamer} from '@github-ui/copilot-chat/utils/copilot-chat-message-streamer'
import {useEffect, useState, useCallback} from 'react'
import {useSessionContext} from '../contexts/SessionContext'
import {useCurrentRepository} from '@github-ui/current-repository'
import {fetchCAPI} from '../utils/fetch-capi'
import {useQueryClient} from '@github-ui/react-query'
import {useAgentSessionsAlive} from './use-agent-sessions-alive'
import {isFeatureEnabled} from '@github-ui/feature-flags'

export const CONSECUTIVE_FAILURE_TOLERANCE = 10

export interface UseSessionLogsProps {
  logsPollingInterval: number
  batchCompletedSessions?: boolean // can be deleted with session logs page
  currentUserIsSessionOwner?: boolean
}

export function useLogs({
  logsPollingInterval,
  batchCompletedSessions = true,
  currentUserIsSessionOwner,
}: UseSessionLogsProps) {
  const {session, logs: preQueriedLogs, logsAreLoading: inactiveLogsLoading} = useSessionContext()
  const repo = useCurrentRepository()
  const queryClient = useQueryClient()
  const isAliveEnabled = isFeatureEnabled('copilot_agent_sessions_alive_updates')

  const [consecutiveFailures, setConsecutiveFailures] = useState(0)
  const activeSessionId = session.id

  const sessionCompleted = [SessionState.Completed, SessionState.Failed, SessionState.Cancelled]
    .map(state => state.toLowerCase())
    .includes(session.state)

  // If the current user doesn't own the session, that means our inactive logs query won't return anything
  const useCachedLogs = batchCompletedSessions && currentUserIsSessionOwner && sessionCompleted

  const handleLogUpdate = useCallback(() => {
    queryClient.invalidateQueries({
      queryKey: ['agent-pr-session-logs', activeSessionId, repo.ownerLogin, repo.name],
    })
  }, [queryClient, activeSessionId, repo.ownerLogin, repo.name])

  // Subscribe to alive log updates if feature flag is enabled
  useAgentSessionsAlive({
    onEvent: handleLogUpdate,
    enableCreateEvents: false,
    enableUpdateEvents: false,
    enableLogUpdates: true,
    enabled: isAliveEnabled,
  })

  const query = useCAPIQuery<LogEntry[]>({
    queryKey: ['agent-pr-session-logs', activeSessionId, repo.ownerLogin, repo.name],
    queryFn: async () => {
      const result = await fetchCAPI({
        path: `/agents/sessions/${activeSessionId}/logs`,
        streamingResponse: true,
      })

      const reader = result.body?.getReader()
      if (!reader) {
        throw new Error('No reader found in response body')
      }

      const logs: LogEntry[] = []
      try {
        const streamer = new CopilotChatMessageStreamer<StreamingMessage>(reader)

        for await (const message of streamer.stream()) {
          if (isValidLogEntry(message)) {
            logs.push(message)
          } else {
            throw new Error(`Invalid log entry received: ${JSON.stringify(message)}`)
          }
        }

        setConsecutiveFailures(0)
        return logs
      } catch (error) {
        throw new Error(`Error while streaming logs. Error: ${error}`)
      }
    },
    refetchInterval: isAliveEnabled || session.state === SessionState.Completed ? false : logsPollingInterval,
    // Turn off log polling after 10 consecutive failures
    enabled: !isPendingSession(session) && !useCachedLogs && consecutiveFailures < CONSECUTIVE_FAILURE_TOLERANCE,
  })

  useEffect(() => {
    if (query.error) {
      setConsecutiveFailures(prev => prev + 1)
    }
  }, [query.error])

  const showPollingError = query.error && consecutiveFailures >= CONSECUTIVE_FAILURE_TOLERANCE

  if (useCachedLogs && (preQueriedLogs?.length || inactiveLogsLoading)) {
    return {
      data: preQueriedLogs,
      isLoading: inactiveLogsLoading,
      error: false,
      showPollingError,
    }
  } else {
    return {
      ...query,
      showPollingError,
    }
  }
}
