import {useCAPIQuery} from './useCAPIQuery'
import {SessionState, type Session} from '../types/session'
import {useCurrentRepository} from '@github-ui/current-repository'
import {fetchCAPI} from '../utils/fetch-capi'
import {useState, useRef, useCallback} from 'react'
import {useParams, useSearchParams} from '@github-ui/react-router'
import {useQueryClient} from '@github-ui/react-query'
import {useAgentSessionsAlive} from './use-agent-sessions-alive'
import {isFeatureEnabled} from '@github-ui/feature-flags'
export const CONSECUTIVE_FAILURE_TOLERANCE = 10

export interface UseAgentSessionsProps {
  // In the future, we might want to update `useSessions` to accept a taskId instead of a pullId
  pullId: number
  sessionsPollingInterval: number
  initialData?: Session[] | undefined
}

export function useSessions({pullId, initialData, sessionsPollingInterval}: UseAgentSessionsProps) {
  const repo = useCurrentRepository()
  const [consecutiveFailures, setConsecutiveFailures] = useState(0)
  const [timedOut, setHasTimedOut] = useState(false)
  const isRetrying = consecutiveFailures > 0 && !timedOut
  // DEPRECATED: session_id is a built in url param for the session logs page
  const params = useParams<{session_id?: string}>()
  // ?session_id=<session_id> is how we query for session in mission control
  const [searchParams] = useSearchParams()
  const sessionIdInQueryParams = searchParams.get('session_id')
  const sessionIdFromUrl = params.session_id || sessionIdInQueryParams
  const queryByTask = useRef(true)
  const queryClient = useQueryClient()
  const isAliveEnabled = isFeatureEnabled('copilot_agent_sessions_alive_updates')

  const handleAliveUpdate = useCallback(() => {
    queryClient.invalidateQueries({
      queryKey: ['agent-sessions', repo.ownerLogin, repo.name, pullId],
    })
  }, [queryClient, repo.ownerLogin, repo.name, pullId])

  // Subscribe to alive updates if feature flag is enabled
  useAgentSessionsAlive({
    onEvent: handleAliveUpdate,
    enableCreateEvents: true,
    enableUpdateEvents: true,
    enableLogUpdates: true,
    enabled: isAliveEnabled,
  })

  const query = useCAPIQuery<Session[]>({
    queryKey: ['agent-sessions', repo.ownerLogin, repo.name, pullId],
    queryFn: async () => {
      try {
        let sessions: Session[] = []
        if (queryByTask.current) {
          const response = await fetchCAPI({
            path: `/agents/sessions/resource/pull/${pullId}`,
          })
          const data = await response.json()
          sessions = data.sessions as Session[]
          const urlSessionInQuery = sessions.some(session => session.id === sessionIdFromUrl)

          if (sessions.length === 0 || (sessionIdFromUrl && !urlSessionInQuery)) {
            queryByTask.current = false
          }
        }

        if (!queryByTask.current) {
          const sessionResponse = await fetchCAPI({
            path: `/agents/sessions/${sessionIdFromUrl}`,
          })
          const sessionData = await sessionResponse.json()
          if (sessionData && sessionData.id) {
            sessions = [sessionData]
          }
        }

        // Reset consecutive failures on successful fetch
        setConsecutiveFailures(0)
        setHasTimedOut(false)

        return sessions.sort((a, b) => {
          // Sort sessions by creation date, most recent first
          return new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
        })
      } catch (error) {
        // Increment consecutive failures on error
        setConsecutiveFailures(prev => {
          const newCount = prev + 1
          if (newCount >= CONSECUTIVE_FAILURE_TOLERANCE) {
            setHasTimedOut(true)
          }
          return newCount
        })
        throw error // Re-throw to maintain React Query error state
      }
    },
    initialData,
    refetchInterval: capiQuery => {
      if (isAliveEnabled) return false

      const data = capiQuery.state.data
      // If no data yet, use default interval
      if (!data) return sessionsPollingInterval

      // Check if any sessions are in active/running state where we want to poll at the default rate
      const hasActiveSessions = data.some(
        session =>
          session.state === SessionState.InProgress ||
          session.state === SessionState.Idle ||
          session.state === SessionState.WaitingForUser ||
          session.state === SessionState.Queued,
      )

      // Slow down polling by a factor of 10 if there are no active sessions. Will speed back up
      // as soon as a session becomes active.
      return hasActiveSessions ? sessionsPollingInterval : sessionsPollingInterval * 10
    },
    // Stop polling after consecutive failure tolerance is reached
    enabled: consecutiveFailures < CONSECUTIVE_FAILURE_TOLERANCE,
  })

  return {
    ...query,
    timedOut,
    isRetrying,
  }
}
